mapper.update:
update sys_menu
parent_id = #{parentId}, menu_name = #{menuName}, path = #{path}, component = #{component}, perms = #{perms}, menu_type = #{menuType}, icon = #{icon}, sort = #{sort}, status = #{status}, delete_flag = #{deleteFlag}, update_time = #{updateTime},
where id = #{id}

WITH RECURSIVE menu_tree AS (
    SELECT id FROM sys_menu WHERE id = #{id}
    UNION ALL
    SELECT child.id
    FROM sys_menu child
    INNER JOIN menu_tree parent ON child.parent_id = parent.id
)
UPDATE sys_menu
SET status = #{status}, update_time = NOW()
WHERE id IN (SELECT id FROM menu_tree);

